package com.modelrag.server.health;
import java.net.URI; import java.net.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.health.contributor.*; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Component;
@Component("elasticsearch") @Profile("!test") public class ElasticsearchHealthIndicator implements HealthIndicator {private final String endpoint;private final HttpClient http=HttpClient.newHttpClient();public ElasticsearchHealthIndicator(@Value("${modelrag.elasticsearch.endpoint:http://localhost:9200}")String endpoint){this.endpoint=endpoint;}public Health health(){try{int status=http.send(HttpRequest.newBuilder(URI.create(endpoint+"/_cluster/health")).GET().build(),HttpResponse.BodyHandlers.discarding()).statusCode();return status==200?Health.up().build():Health.down().withDetail("httpStatus",status).build();}catch(Exception e){return Health.down(e).build();}}}
